    def parse_ohlcv(self, ohlcv: object, market: Market = None) -> list:
        #
        #     {
        #         "Time": 1708416900,
        #         "Open": 51707.52,
        #         "High": 51707.52,
        #         "Low": 51707.52,
        #         "Close": 51707.52,
        #         "Volume": "0"
        #     }
        #
        return [
            self.safe_timestamp(ohlcv, 'Time'),
            self.safe_number(ohlcv, 'Open'),
            self.safe_number(ohlcv, 'High'),
            self.safe_number(ohlcv, 'Low'),
            self.safe_number(ohlcv, 'Close'),
            self.safe_number(ohlcv, 'Volume'),
        ]

    async def fetch_ohlcv(self, symbol: str, timeframe: str = '1m', since: Int = None, limit: Int = None, params: dict = {}) -> list[list]:
        """
        fetches historical candlestick data containing the open, high, low, and close price, and the volume of a market
        :param str symbol: unified symbol of the market to fetch OHLCV data for
        :param str timeframe: the length of time each candle represents
        :param int [since]: timestamp in ms of the earliest candle to fetch
        :param int [limit]: the maximum amount of candles to fetch
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param int [params.until]: timestamp in ms of the latest candle to fetch
        :returns int[][]: A list of candles ordered as timestamp, open, high, low, close, volume
        """
        if self.markets is None:
            await self.load_markets()
        market = self.market(symbol)
        selectedTimeframe = self.safe_string(self.timeframes, timeframe, timeframe)
        now = self.seconds()
        until = self.safe_integer(params, 'until', now)
        params = self.omit(params, ['until'])
        request = {
            'to': until,
            'tf': selectedTimeframe,
            'symbol': market['id'],
        }
        if limit is None:
            limit = 1000
        if since is not None:
            request['from'] = int(math.floor(since / 1000))
        else:
            duration = self.parse_timeframe(timeframe)
            request['from'] = now - limit * duration - 1
        response = await self.publicGetTradingviewHistoryV2(self.extend(request, params))
        #
        #     [
        #         {
        #             "Time": 1708416900,
        #             "Open": 51707.52,
        #             "High": 51707.52,
        #             "Low": 51707.52,
        #             "Close": 51707.52,
        #             "Volume": "0"
        #         }
        #     ]
        #
        return self.parse_ohlcvs(self.to_array(response), market, timeframe, since, limit)

    def parse_order_status(self, status: Str):
        statuses = {
            'open': 'open',
            'filled': 'closed',
            'cancelled': 'canceled',
            'NEW': 'open',
            'PARTIALLY_FILLED': 'open',
            'FILLED': 'closed',
            'CANCELLED': 'canceled',
            'CANCELED': 'canceled',
            'REJECTED': 'rejected',
            'EXPIRED': 'expired',
        }
        return self.safe_string(statuses, status, status)

    def parse_order(self, order: dict, market: Market = None) -> Order:
        if ('origQty' in order) or ('oriQty' in order) or ('fullOrderId' in order) or ('executedQty' in order):
            return self.parse_v2_order(order, market)
        #
        #     {
        #         "order_id": "12345",
        #         "submit_time": "1392228122",
        #         "price": "8000000",
        #         "type": "sell",
        #         "order_ltc": "100000000",
        #         "remain_ltc": "100000000"
        #     }
        #
        # market closed orders - note that the price is very high
        # and does not reflect actual price the order executed at
        #
        #     {
        #       "order_id": "49326856",
        #       "type": "sell",
        #       "price": "1000000000",
        #       "submit_time": "1618314671",
        #       "finish_time": "1618314671",
        #       "status": "filled",
        #       "order_xrp": "30.45000000",
        #       "remain_xrp": "0.00000000"
        #     }
        #
        # cancelOrder
        #
        #    {
        #        "order_id": 666883,
        #        "client_order_id": "clientx-sj82ks82j",
        #        "type": "sell",
        #        "pair": "btc_idr",
        #        "balance": {
        #            "idr": "33605800",
        #            "btc": "0.00000000",
        #            ...
        #            "frozen_idr": "0",
        #            "frozen_btc": "0.00000000",
        #            ...
        #        }
        #    }
        #
        side = None
        if 'type' in order:
            side = order['type']
        status = self.parse_order_status(self.safe_string(order, 'status', 'open'))
        symbol = None
        cost = None
        price = self.safe_string(order, 'price')
        amount = None
        remaining = None
        filled = None
        marketId = self.safe_string(order, 'pair')
        market = self.safe_market(marketId, market)
        if market is not None:
            symbol = market['symbol']
            quoteId = self.safe_string(market, 'quoteId')
            baseId = self.safe_string(market, 'baseId')
            if (quoteId is None) or (baseId is None):
                resolved = self.market_from_v1_pair(marketId)
                resolvedQuoteId = self.safe_string(resolved, 'quoteId')
                resolvedBaseId = self.safe_string(resolved, 'baseId')
                if resolvedQuoteId is not None:
                    quoteId = resolvedQuoteId
                    symbol = self.safe_string(resolved, 'symbol', symbol)
                if resolvedBaseId is not None:
                    baseId = resolvedBaseId
            if (quoteId == 'idr') and ('order_rp' in order):
                quoteId = 'rp'
            if (baseId == 'idr') and ('remain_rp' in order):
                baseId = 'rp'
            if quoteId is not None:
                costKey = 'order_' + quoteId
                cost = self.safe_string(order, costKey)
            if baseId is not None:
                amountKey = 'order_' + baseId
                remainKey = 'remain_' + baseId
                filledKey = 'receive_' + baseId
                amount = self.safe_string(order, amountKey)
                remaining = self.safe_string(order, remainKey)
                # filled buy orders on idr-quoted markets carry the executed base amount
                # only in a dynamic receive_{base} field, https://github.com/ccxt/ccxt/issues/26413
                filled = self.safe_string(order, filledKey)
        timestamp = self.safe_integer(order, 'submit_time')
        fee = None
        id = self.safe_string(order, 'order_id')
        return self.safe_order({
            'info': order,
            'id': id,
            'clientOrderId': self.safe_string(order, 'client_order_id'),
            'timestamp': timestamp,
            'datetime': self.iso8601(timestamp),
            'lastTradeTimestamp': None,
            'symbol': symbol,
            'type': 'limit',
            'timeInForce': None,
            'postOnly': None,
            'side': side,
            'price': price,
            'triggerPrice': None,
            'cost': cost,
            'average': None,
            'amount': amount,
            'filled': filled,
            'remaining': remaining,
            'status': status,
            'fee': fee,
            'trades': None,
        })

    async def fetch_order(self, id: str, symbol: Str = None, params: dict = {}) -> Order:
        """
        fetches information on an order made by the user

        https://github.com/btcid/indodax-official-api-docs/blob/master/Private-RestAPI.md#get-order-endpoints
        https://github.com/btcid/indodax-official-api-docs/blob/master/INDODAX-TradeAPI-2.md#get-order

        :param str id: order id
        :param str symbol: unified symbol of the market the order was made in
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param str [params.clientOrderId]: client order id, only used when options.tapiVersion is "2"
        :returns dict: An `order structure <https://docs.ccxt.com/?id=order-structure>`
        """
        if self.is_tapi_v2():
            return await self.order_v2(id, symbol, params)
        if symbol is None:
            raise ArgumentsRequired(self.id + ' fetchOrder() requires a symbol argument')
        if self.markets is None:
            await self.load_markets()
        market = self.market(symbol)
        request = {
            'pair': self.v1_pair_id(market),
            'order_id': id,
        }
        response = await self.privatePostGetOrder(self.extend(request, params))
        orders = self.safe_dict(response, 'return', {})
        order = self.parse_order(self.extend({'id': id}, orders['order']), market)
        order['info'] = response
        return order

    async def fetch_open_orders(self, symbol: Str = None, since: Int = None, limit: Int = None, params: dict = {}) -> list[Order]:
        """
        fetch all unfilled currently open orders

        https://github.com/btcid/indodax-official-api-docs/blob/master/Private-RestAPI.md#open-orders-endpoints
        https://github.com/btcid/indodax-official-api-docs/blob/master/INDODAX-TradeAPI-2.md#pending-order

        :param str symbol: unified market symbol
        :param int [since]: the earliest time in ms to fetch open orders for
        :param int [limit]: the maximum number of  open orders structures to retrieve
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns Order[]: a list of `order structures <https://docs.ccxt.com/?id=order-structure>`
        """
        if self.is_tapi_v2():
            return await self.open_orders_v2(symbol, since, limit, params)
        if self.markets is None:
            await self.load_markets()
        market = None
        request = {}
        if symbol is not None:
            market = self.market(symbol)
            request['pair'] = self.v1_pair_id(market)
        response = await self.privatePostOpenOrders(self.extend(request, params))
        openOrdersResult = self.safe_dict(response, 'return', {})
        rawOrders = openOrdersResult['orders']
        # { success: 1, return: { orders: null }} if no orders
        if (rawOrders is None) or (rawOrders is None):
            return []
        # { success: 1, return: { orders: [ ... objects ] }} for orders fetched by symbol
        if symbol is not None:
            return self.parse_orders(rawOrders, market, since, limit)
        # { success: 1, return: { orders: { marketid: [ ... objects ] }}} if all orders are fetched
        marketIds = list(rawOrders.keys())
        exchangeOrders = []
        for i in range(0, len(marketIds)):
            marketId = marketIds[i]
            marketOrders = rawOrders[marketId]
            market = self.market_from_v1_pair(marketId)
            parsedOrders = self.parse_orders(marketOrders, market, since, limit)
            exchangeOrders = self.array_concat(exchangeOrders, parsedOrders)
        return exchangeOrders

    async def fetch_closed_orders(self, symbol: Str = None, since: Int = None, limit: Int = None, params: dict = {}) -> list[Order]:
        """
        fetches information on multiple closed orders made by the user

        https://github.com/btcid/indodax-official-api-docs/blob/master/Private-RestAPI.md#order-history
        https://github.com/btcid/indodax-official-api-docs/blob/master/INDODAX-TradeAPI-2.md#order-history

        :param str symbol: unified market symbol of the market orders were made in
        :param int [since]: the earliest time in ms to fetch orders for
        :param int [limit]: the maximum number of order structures to retrieve
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns Order[]: a list of `order structures <https://docs.ccxt.com/?id=order-structure>`
        """
        if self.is_tapi_v2():
            closedOrders = await self.fetch_orders(symbol, since, limit, params)
            return self.filter_by(closedOrders, 'status', 'closed')
        if symbol is None:
            raise ArgumentsRequired(self.id + ' fetchClosedOrders() requires a symbol argument')
        if self.markets is None:
            await self.load_markets()
        market = self.market(symbol)
        request = {
            'pair': self.v1_pair_id(market),
        }
        response = await self.privatePostOrderHistory(self.extend(request, params))
        historyResult = self.safe_dict(response, 'return', {})
        orders = self.parse_orders(historyResult['orders'], market)
        orders = self.filter_by(orders, 'status', 'closed')
        return self.filter_by_symbol_since_limit(orders, symbol, since, limit)

    async def create_order(self, symbol: str, type: OrderType, side: OrderSide, amount: float, price: Num = None, params: dict = {}) -> Order:
        """
        create a trade order

        https://github.com/btcid/indodax-official-api-docs/blob/master/Private-RestAPI.md#trade-endpoints
        https://github.com/btcid/indodax-official-api-docs/blob/master/INDODAX-TradeAPI-2.md#create-order

        :param str symbol: unified symbol of the market to create an order in
        :param str type: 'market' or 'limit'
        :param str side: 'buy' or 'sell'
        :param float amount: how much of currency you want to trade in units of base currency
        :param float [price]: the price at which the order is to be fulfilled, in units of the quote currency, ignored in market orders
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param float [params.cost]: quote amount to spend on a market buy, only used when options.tapiVersion is "2"
        :param str [params.clientOrderId]: client order id, only used when options.tapiVersion is "2"
        :param str [params.timeInForce]: GTC or MOC, only used when options.tapiVersion is "2"
        :param str [params.selfTradePreventionMode]: EXPIRE_TAKER, EXPIRE_MAKER, or EXPIRE_BOTH, only used when options.tapiVersion is "2"
        :returns dict: an `order structure <https://docs.ccxt.com/?id=order-structure>`
        """
        if self.is_tapi_v2():
            return await self.place_order_v2(symbol, type, side, amount, price, params)
        if self.markets is None:
            await self.load_markets()
        market = self.market(symbol)
        request = {
            'pair': self.v1_pair_id(market),
            'type': side,
            'price': price,
        }
        priceIsRequired = False
        quantityIsRequired = False
        if type == 'market':
            if side == 'buy':
                quoteAmount = None
                cost = self.safe_number(params, 'cost')
                params = self.omit(params, 'cost')
                if cost is not None:
                    quoteAmount = self.cost_to_precision(symbol, cost)
                else:
                    if price is None:
                        raise InvalidOrder(self.id + ' createOrder() requires the price argument for market buy orders to calculate the total cost to spend (amount * price).')
                    amountString = self.number_to_string(amount)
                    priceString = self.number_to_string(price)
                    costRequest = Precise.string_mul(amountString, priceString)
                    quoteAmount = self.cost_to_precision(symbol, costRequest)
                request[market['quoteId']] = quoteAmount
            else:
                quantityIsRequired = True
        elif type == 'limit':
            priceIsRequired = True
            quantityIsRequired = True
            if side == 'buy':
                request[market['quoteId']] = self.parse_to_numeric(self.cost_to_precision(symbol, Precise.string_mul(self.number_to_string(amount), self.number_to_string(price))))
        if priceIsRequired:
            if price is None:
                raise InvalidOrder(self.id + ' createOrder() requires a price argument for a ' + type + ' order')
            request['price'] = price
        if quantityIsRequired:
            request[market['baseId']] = self.amount_to_precision(symbol, amount)
        result = await self.privatePostTrade(self.extend(request, params))
        data = self.safe_dict(result, 'return', {})
        id = self.safe_string(data, 'order_id')
        return self.safe_order({
            'info': result,
            'id': id,
        }, market)

    async def cancel_order(self, id: str, symbol: Str = None, params: dict = {}) -> Order:
        """
        cancels an open order

        https://github.com/btcid/indodax-official-api-docs/blob/master/Private-RestAPI.md#cancel-order-endpoints
        https://github.com/btcid/indodax-official-api-docs/blob/master/INDODAX-TradeAPI-2.md#cancel-order

        :param str id: order id
        :param str symbol: unified symbol of the market the order was made in
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :param str [params.side]: order side, required on TAPI v1 and not used when options.tapiVersion is "2"
        :param str [params.clientOrderId]: client order id, only used when options.tapiVersion is "2"
        :returns dict: An `order structure <https://docs.ccxt.com/?id=order-structure>`
        """
        if self.is_tapi_v2():
            return await self.remove_order_v2(id, symbol, params)
        if symbol is None:
            raise ArgumentsRequired(self.id + ' cancelOrder() requires a symbol argument')
        side = self.safe_value(params, 'side')
        if side is None:
            raise ArgumentsRequired(self.id + ' cancelOrder() requires an extra "side" param')
        if self.markets is None:
            await self.load_markets()
        market = self.market(symbol)
        request = {
            'order_id': id,
            'pair': self.v1_pair_id(market),
            'type': side,
        }
        response = await self.privatePostCancelOrder(self.extend(request, params))
        #
        #    {
        #        "success": 1,
        #        "return": {
        #            "order_id": 666883,
        #            "client_order_id": "clientx-sj82ks82j",
        #            "type": "sell",
        #            "pair": "btc_idr",
        #            "balance": {
        #                "idr": "33605800",
        #                "btc": "0.00000000",
        #                ...
        #                "frozen_idr": "0",
        #                "frozen_btc": "0.00000000",
        #                ...
        #            }
        #        }
        #    }
        #
        data = self.safe_dict(response, 'return')
        return self.parse_order(data)

    async def fetch_transaction_fee(self, code: str, params: dict = {}):
        """
        fetch the fee for a transaction

        https://github.com/btcid/indodax-official-api-docs/blob/master/Private-RestAPI.md#withdraw-fee-endpoints

        :param str code: unified currency code
        :param dict [params]: extra parameters specific to the exchange API endpoint
        :returns dict: a `fee structure <https://docs.ccxt.com/?id=fee-structure>`
        """
        if self.is_tapi_v2():
            raise NotSupported(self.id + ' fetchTransactionFee() is not available when options.tapiVersion is "2"')
        if self.markets is None:
            await self.load_markets()
        currency = self.currency(code)
        request = {
            'currency': currency['id'],
        }
        response = await self.privatePostWithdrawFee(self.extend(request, params))
        #
        #     {
        #         "success": 1,
        #         "return": {
        #             "server_time": 1607923272,
        #             "withdraw_fee": 0.005,
        #             "currency": "eth"
        #         }
        #     }
        #
        data = self.safe_dict(response, 'return', {})
